/* xx_ar_extractor.c - search raw data for AR.
 *
 * Scans for:
 *   21 3C 61 72 63 68 3E 0A at +0  ("!<arch>.")
 *   21 3C 74 68 69 6E 3E 0A at +0  ("!<thin>.")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the ar reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/ar/xx_ar.h"

static const uint8_t k_anchor0[] = { 0x21, 0x3C, 0x61, 0x72, 0x63, 0x68, 0x3E, 0x0A };
static const uint8_t k_anchor1[] = { 0x21, 0x3C, 0x74, 0x68, 0x69, 0x6E, 0x3E, 0x0A };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
    { k_anchor1, sizeof(k_anchor1), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_AR };

static Abstractformat *xx_ar_search_open(xx_io_device *window) {
    xx_ar *reader = xx_ar_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_ar_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_ar_free((xx_ar *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_ar_search_open, xx_ar_search_close
};

static xx_format_search_state *xx_ar_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_ar_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_ar_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_ar_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_ar_extractor = {
    xx_ar_create_format_search,
    xx_ar_get_current_format_info,
    xx_ar_format_search_find_next,
    xx_ar_free_format_search
};
